class DataStatistics4 {

    /*
    This is a class that performs advanced mathematical calculations and statistics, including correlation coefficient, skewness, kurtosis, and probability density function (PDF) for a normal distribution.
    */

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        /*
        Calculate the correlation coefficient of two sets of data.
        :param data1: The first set of data,ArrayList<Float64>.
        :param data2: The second set of data,ArrayList<Float64>.
        :return: The correlation coefficient, Float64.
        >>> DataStatistics4.correlation_coefficient(ArrayList<Float64>([1.0, 2.0, 3.0]), ArrayList<Float64>([4.0, 5.0, 6.0]))
        0.9999999999999998

        */
        let n1 = data1.size
        let n2 = data2.size
        if (n1 == 0 || n2 == 0 || n1 != n2) {
            return 0.0
        }
        var sumx: Float64 = 0.0
        var sumy: Float64 = 0.0
        for (i in 0..n1) {
            sumx += data1[i]
            sumy += data2[i]
        }
        let nf = Float64(n1)
        let meanx = sumx / nf
        let meany = sumy / nf

        var num: Float64 = 0.0
        var sx2: Float64 = 0.0
        var sy2: Float64 = 0.0
        for (i in 0..n1) {
            let dx = data1[i] - meanx
            let dy = data2[i] - meany
            num += dx * dy
            sx2 += dx * dx
            sy2 += dy * dy
        }
        let denom = sqrt(sx2 * sy2)
        if (denom == 0.0) {
            return 0.0
        }
        return num / denom
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        /*
        Calculate the skewness of a set of data.
        :param data: The input data list, ArrayList<Float64>.
        :return: The skewness, Float64.
        >>> DataStatistics4.skewness(ArrayList<Float64>([1.0, 2.0, 5.0]))
        2.3760224064818463

        */
        let n = data.size
        if (n <= 1) {
            return 0.0
        }
        var sum: Float64 = 0.0
        for (i in 0..n) { sum += data[i] }
        let nf = Float64(n)
        let mean = sum / nf

        var s2_sum: Float64 = 0.0
        var s3_sum: Float64 = 0.0
        for (i in 0..n) {
            let d = data[i] - mean
            let d2 = d * d
            s2_sum += d2
            s3_sum += d2 * d
        }
        if (s2_sum == 0.0) {
            return 0.0
        }
        // Use population variance in the denominator and apply a small-sample correction factor n/(n-1)
        let var_pop = s2_sum / nf
        let sigma3 = sqrt(var_pop) * var_pop
        if (sigma3 == 0.0) {
            return 0.0
        }
        let corr = nf / Float64(n - 1)
        return corr * (s3_sum / sigma3)
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        /*
        Calculate the kurtosis of a set of data.
        :param data: The input data list, ArrayList<Float64>.
        :return: The kurtosis, Float64.
        >>> DataStatistics4.kurtosis(ArrayList<Float64>([1.0, 2.0, 5.0]))
        -1.5000000000000007

        */
        let n = data.size
        if (n == 0) {
            return 0.0
        }
        var sum: Float64 = 0.0
        for (i in 0..n) { sum += data[i] }
        let nf = Float64(n)
        let mean = sum / nf

        var s2_sum: Float64 = 0.0
        var s4_sum: Float64 = 0.0
        for (i in 0..n) {
            let d = data[i] - mean
            let d2 = d * d
            s2_sum += d2
            s4_sum += d2 * d2
        }
        if (s2_sum == 0.0) {
            // Excess kurtosis for degenerate distribution can be treated as -3.0
            return -3.0
        }
        let m2 = s2_sum / nf
        let m4 = s4_sum / nf
        return m4 / (m2 * m2) - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        /*
        Calculate the probability density function (PDF) of a set of data under a normal distribution.
        :param data: The input data list, ArrayList<Float64>.
        :param mu: The mean of the normal distribution, Float64.
        :param sigma: The standard deviation of the normal distribution, Float64.
        :return: The probability density function (PDF), ArrayList<Float64>.
        >>> DataStatistics4.pdf(ArrayList<Float64>([1.0, 2.0, 3.0]), 1.0, 1.0)
        [0.3989422804014327, 0.24197072451914337, 0.05399096651318806]

        */
        let n = data.size
        let res = ArrayList<Float64>()
        if (sigma <= 0.0) {
            for (_ in 0..n) { res.add(0.0) }
            return res
        }
        let twoPi = 2.0 * Float64.getPI()
        let coef = 1.0 / (sigma * sqrt(twoPi))
        let twoSigma2 = 2.0 * sigma * sigma
        for (i in 0..n) {
            let x = data[i]
            let diff = x - mu
            let e = exp(-(diff * diff) / twoSigma2)
            res.add(coef * e)
        }
        return res
    }
}

import std.collection.ArrayList

class DecryptionUtils {

    /*
    This is a class that provides methods for decryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the decryption utility with a key.
        :param key: The key to use for decryption,String.
        */
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        /*
        Deciphers the given ciphertext using the Caesar cipher
        :param ciphertext: The ciphertext to decipher,String.
        :param shift: The shift to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.caesar_decipher('ifmmp', 1)
        'hello'

        */
        var sb = StringBuilder()
        let runes = ciphertext.toRuneArray()

        var s = shift % 26
        if (s < 0) {
            s += 26
        }

        for (c in runes) {
            if (c.isAsciiLetter()) {
                var base: Rune
                var basePos: Int64
                if (c.isAsciiUpperCase()) {
                    base = r'A'
                    basePos = r'A'.position()
                } else {
                    base = r'a'
                    basePos = r'a'.position()
                }
                var offset = c.position() - basePos
                var newOffset = (offset - s) % 26
                if (newOffset < 0) { newOffset += 26 }
                sb.append(base.next(newOffset))
            } else {
                sb.append(c)
            }
        }

        return sb.toString()
    }

    public func vigenere_decipher(ciphertext: String): String {
        /*
        Deciphers the given ciphertext using the Vigenere cipher
        :param ciphertext: The ciphertext to decipher,String.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.vigenere_decipher('ifmmp')
        'ybocl'

        */
        let keyRunes = this.key.toRuneArray()
        let klen = keyRunes.size
        if (klen == 0) {
            return ciphertext
        }

        var sb = StringBuilder()
        var ki: Int64 = 0

        for (c in ciphertext.toRuneArray()) {
            if (c.isAsciiLetter()) {
                let kr = keyRunes[ki % klen]
                let kl = kr.toAsciiLowerCase()

                var shiftVal: Int64 = 0
                if (kl.isAsciiLetter()) {
                    shiftVal = kl.position() - r'a'.position()
                }

                var base: Rune
                var basePos: Int64
                if (c.isAsciiUpperCase()) {
                    base = r'A'
                    basePos = r'A'.position()
                } else {
                    base = r'a'
                    basePos = r'a'.position()
                }
                var offset = c.position() - basePos
                var newOffset = (offset - shiftVal) % 26
                if (newOffset < 0) { newOffset += 26 }
                sb.append(base.next(newOffset))

                ki++
            } else {
                sb.append(c)
            }
        }
        return sb.toString()
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        /*
        Deciphers the given ciphertext using the Rail Fence cipher
        :param encrypted_text: The ciphertext to decipher,String.
        :param rails: The number of rails to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.rail_fence_decipher('Hoo!el,Wrdl l', 3)
        'Hello, World!'

        */
        let chars = encrypted_text.toRuneArray()
        let n = chars.size
        if (rails <= 1 || n == 0) {
            return encrypted_text
        }

        var R: Int64 = rails
        if (R > n) { R = n }

        // First pass: count how many characters belong to each rail
        var counts = Array<Int64>(R, repeat: 0)
        var row: Int64 = 0
        var dir: Int64 = 1
        var i: Int64 = 0
        while (i < n) {
            counts[row] = counts[row] + 1
            row += dir
            if (row == 0 || row == R - 1) {
                dir = -dir
            }
            i++
        }

        // Compute starting index in encrypted text for each rail
        var starts = Array<Int64>(R, repeat: 0)
        var acc: Int64 = 0
        var r: Int64 = 0
        while (r < R) {
            starts[r] = acc
            acc += counts[r]
            r++
        }

        // Pointers into each rail segment
        var pointers = Array[Int64](R, repeat: 0)
        r = 0
        while (r < R) {
            pointers[r] = starts[r]
            r++
        }

        // Second pass: reconstruct plaintext following zigzag traversal
        var sb = StringBuilder()
        row = 0
        dir = 1
        i = 0
        while (i < n) {
            let idx = pointers[row]
            sb.append(chars[idx])
            pointers[row] = idx + 1

            row += dir
            if (row == 0 || row == R - 1) {
                dir = -dir
            }
            i++
        }

        return sb.toString()
    }
}

